def bushy(total):
    if total == 1: return {'op':'true'}
    kids = total - 1
    n = min(32, kids)
    sizes = [1]*n
    left = kids - n
    i = 0
    while left > 0:
        j = i % n
        if sizes[j] == 1:
            sizes[j] = 2; left -= 1
        elif sizes[j] < 32:
            sizes[j] += 1; left -= 1
        i += 1
    args = [bushy(sz) if sz > 1 else {'op':'true'} for sz in sizes]
    return {'op':'and','args':args}

def count(e):
    if e['op'] in ('true','false'): return 1
    if 'path' in e: return 1
    if e['op']=='not': return 1+count(e['arg'])
    return 1+sum(count(a) for a in e['args'])
def maxargs(e):
    r = 0
    if e['op'] in ('and','or'):
        r = len(e['args'])
        for a in e['args']: r = max(r, maxargs(a))
    elif e['op']=='not': r = maxargs(e['arg'])
    return r
